    { name: "Strengthen crisis-sensitive education recovery", period: "2026", stage: "Education system resilience", description: "UNESCO works with national authorities to support affected schools, equip digital learning options and build crisis-sensitive capacity among teachers and school leaders as education systems recover.", actor: "UNESCO / Ministry of Education and Higher Education / Lebanese University / education partners", href: "https://www.unesco.org/en/articles/unesco-steps-support-lebanons-crisis-unfolds" },
    { name: "Assess cultural heritage damage and prepare emergency rehabilitation", period: "Cross-cutting", stage: "Cultural heritage recovery", description: "UNESCO led rapid cultural-heritage damage assessment and risk-preparedness work to guide emergency rehabilitation of priority sites affected by hostilities, including in Tyre and Baalbek.", actor: "UNESCO / national heritage authorities / local cultural partners", href: "https://www.unesco.org/en/node/208725" },
    { name: "Support cultural entities and creative livelihoods in affected areas", period: "Cross-cutting", stage: "Cultural and livelihood recovery", description: "UNESCO emergency funding supports local cultural organisations in Baalbek and Tyre to resume activity, strengthen skills and sustain community cultural life after conflict-related disruption.", actor: "UNESCO Heritage Emergency Fund / local cultural organisations / France", href: "https://www.unesco.org/en/culture-emergencies/heritage-emergency-fund/emergency-funding-support-cultural-and-creative-industries-lebanon" },
    { name: "Supply trauma care, essential medicines and hospital equipment", period: "2026", stage: "Emergency health service continuity", description: "WHO’s emergency distribution plan supports hospitals with trauma emergency surgical kits, essential medicines and critical supplies to sustain care during the escalation.", actor: "WHO / Ministry of Public Health / public and private hospitals / health partners", href: "https://www.emro.who.int/images/stories/lebanon/Lebanon-Emergency-Sitrep-22-2026.pdf" },
    { name: "Expand inpatient mental-health support during the emergency", period: "2026", stage: "Mental-health care", description: "WHO initiated inpatient support for severe mental-health conditions as part of the emergency health response, complementing trauma, medicine and hospital-supply assistance.", actor: "WHO / Ministry of Public Health / health providers", href: "https://www.emro.who.int/images/stories/lebanon/Lebanon-Emergency-Sitrep-22-2026.pdf" },
    { name: "Scale gender-based violence protection and safe spaces", period: "2026", stage: "Protection services", description: "UNFPA and UNHCR co-lead the gender-based violence working group with the Ministry of Social Affairs to strengthen safe spaces and a coordinated, data-driven emergency protection response for women and girls.", actor: "UNFPA / UNHCR / Ministry of Social Affairs / GBV Working Group / protection partners", href: "https://www.unfpa.org/sites/default/files/resource-pdf/UNFPA%20Lebanon%20Situation%20Report%20%282-9%20March%202026%29.pdf" },
    { name: "Guide housing, protection, environment and climate recovery", period: "Cross-cutting", stage: "Integrated urban recovery framework", description: "UN-Habitat’s urban recovery framework links national and local institutions with adequate housing, protection, environment and climate workstreams for areas affected by the post-2023 conflict.", actor: "UN-Habitat / public institutions / local authorities / urban recovery partners", href: "https://unhabitat.org/urban-crisis-response-recovery-and-reconstruction-framework-for-lebanon-urfl" },
    { name: "Coordinate nationwide assistance and resilience", period: "2026", stage: "Coordination", description: "The Lebanon Response Plan links cash, education, food security, health, livelihoods, protection, shelter, social stability and water and sanitation.", actor: "Government of Lebanon / UN partners", href: "https://lebanon.un.org/en/309523-lebanon-response-plan-2026" }
    ,{ name: "Coordinate farmer assistance, training and rehabilitation planning", period: "2026", stage: "Rural livelihoods and infrastructure", description: "The Ministry of Agriculture, European Union, FAO and WFP link the Farmers Registry, cash support, technical training, field damage assessment and identified irrigation and water-storage interventions. These are documented recovery-support and planning measures, not a completed infrastructure register.", actor: "Ministry of Agriculture / European Union / FAO / WFP / farmer-support partners", href: "https://www.fao.org/lebanon/news/detail/ministry-of-agriculture--the-eu--fao-and-wfp-drive-coordinated-action-to-support-food-security-and-rural-livelihoods-in-lebanon/en" }
    ,{ name: "Rehabilitate and equip Minieh ISF station for accessible local policing", period: "2026", stage: "Public safety and service continuity", description: "The Ministry of Interior and Municipalities, Internal Security Forces, Canada and UNDP documented rehabilitation, accessibility upgrades, vehicles and equipment for the Minieh ISF station in Deir Ammar to strengthen day-to-day public service for surrounding communities.", actor: "Ministry of Interior and Municipalities / Internal Security Forces / Government of Canada / UNDP / local authorities", href: "https://www.undp.org/lebanon/press-releases/isf-canada-and-undp-visit-marks-rehabilitation-minieh-isf-station-north-lebanon" }
    ,{ name: "Prepare community-policing station rehabilitation in South Lebanon", period: "2026", stage: "Procurement and service restoration", description: "UNDP’s southern stabilization programme reports completed blueprints and procurement-stage preparation for community-policing station rehabilitation in Marjaayoun, Qana and Nabatieh. This records preparation and procurement progress, not completed works.", actor: "Internal Security Forces / UNDP / local authorities / stabilization partners", href: "https://www.undp.org/lebanon/projects/stabilization-southern-lebanon" }
    ,{ name: "Upgrade vehicle-registration service capacity in Nabatieh", period: "2026", stage: "Administrative service restoration", description: "The southern stabilization programme records procurement preparation for equipment and infrastructure upgrades at the Nabatieh vehicle-registration department to reduce administrative bottlenecks and strengthen public service delivery.", actor: "Vehicle Registration Department / Internal Security Forces / UNDP / local authorities", href: "https://www.undp.org/lebanon/projects/stabilization-southern-lebanon" }
    ,{ name: "Embed gender-responsive planning and women-led enterprise support", period: "2026", stage: "Inclusive local recovery", description: "UNDP’s Local Development Project builds gender-responsive and inclusive planning into municipal development, alongside labour-market links and business-development support for women-led micro, small and medium enterprises.", actor: "Municipalities / Local Development Platforms / UNDP / KfW / women-led enterprises", href: "https://www.undp.org/lebanon/projects/local-development-project-ldp" }
    ,{ name: "Institutionalise community dialogue and peacebuilding in local recovery", period: "2026", stage: "Social stability and local governance", description: "UNDP’s Host Communities Support Project links municipal service delivery and livelihoods with community dialogue and peacebuilding mechanisms intended to reduce tensions and strengthen collaboration between host and displaced communities.", actor: "Municipalities / Unions of Municipalities / UNDP / community partners", href: "https://www.undp.org/lebanon/projects/lebanon-host-communities-support-project-phase-2-lhsp-20" }
    ,{ name: "Sustain accessible agricultural guidance for women farmers", period: "2026", stage: "Inclusive agrifood resilience", description: "FAO used visual materials, voice messages and regular check-ins to help farmers, especially women and people facing literacy or access barriers, retain access to practical agricultural guidance during crisis conditions.", actor: "FAO / Ministry of Agriculture / women farmers / local agricultural networks", href: "https://www.fao.org/lebanon/news/detail/empowering-women-in-crisis--fao-keeps-lebanon-s-farmers-connected/en" }
    ,{ name: "Coordinate field response through area-based operational groups", period: "2026", stage: "Field coordination and local delivery", description: "The Lebanon Response Plan shifts subnational coordination toward operational, area-based groups so partners can align assistance with local government structures, reduce duplication and respond to conditions in each area.", actor: "Inter-Sector Coordination Group / OCHA / UNHCR / UNDP / line ministries / local partners", href: "https://lebanon.un.org/sites/default/files/2026-02/Lebanon%20Response%20Plan%202026.pdf" }
    ,{ name: "Maintain reproductive-health and GBV support for displaced women and girls", period: "2026", stage: "Protection and health-service continuity", description: "UNFPA works with the Ministries of Public Health and Social Affairs, health facilities and protection partners to maintain survivor-centred case management, psychosocial support, safe spaces, mobile services and referral pathways during displacement.", actor: "UNFPA / Ministry of Public Health / Ministry of Social Affairs / health and protection partners", href: "https://www.unfpa.org/resources/situation-report-crisis-lebanon-9-22-june-2026" }
    ,{ name: "Keep shelter-based protection referrals and remote support available", period: "2026", stage: "Shelter protection services", description: "UNFPA-supported services use social-development centres, women and girls safe spaces, primary-health-care facilities and remote channels to sustain information, referrals and psychosocial support when movement or access is constrained.", actor: "UNFPA / Ministry of Social Affairs / Social Development Centres / protection partners", href: "https://www.unfpa.org/sites/default/files/resource-pdf/UNFPA%20Lebanon%20Situation%20Report%20%282-9%20March%202026%29.pdf" }
    ,{ name: "Support informed voluntary return through official procedures", period: "2026", stage: "Returns and durable solutions", description: "UNHCR and IOM provide counselling, individual eligibility checks, documentation guidance and transport for people who choose voluntary return, with the General Directorate of General Security facilitating official administrative and crossing procedures.", actor: "UNHCR / IOM / General Directorate of General Security / Lebanese authorities", href: "https://help.unhcr.org/lebanon/en/welcome/return-to-syria/unhcr-iom-supported-organized-voluntary-return-programme/" }
    ,{ name: "Train community-policing teams on gender-based violence response", period: "2026", stage: "Public safety and protection", description: "The southern stabilization programme includes training for Internal Security Forces on community-policing practice with specific attention to responding to sexual and gender-based violence in conflict-affected localities.", actor: "Internal Security Forces / UNDP / local authorities / stabilization partners", href: "https://www.undp.org/lebanon/projects/stabilization-southern-lebanon" }
    ,{ name: "Build accessibility and safety needs into public-facility rehabilitation", period: "2026", stage: "Inclusive public-service restoration", description: "UNDP’s southern stabilization programme integrates the needs of women, girls and persons with disabilities when rehabilitating public facilities, connecting reconstruction choices to safer and more accessible service delivery.", actor: "UNDP / Internal Security Forces / public institutions / local authorities", href: "https://www.undp.org/lebanon/projects/stabilization-southern-lebanon" }
    ,{ name: "Support female-headed households with recovery income opportunities", period: "2026", stage: "Inclusive livelihood recovery", description: "The southern stabilization programme targets female-headed households for income-generation support and start-up grants as part of a wider approach to stabilisation and longer-term livelihood recovery.", actor: "UNDP / local authorities / female-headed households / livelihood partners", href: "https://www.undp.org/lebanon/projects/stabilization-southern-lebanon" }
    ,{ name: "Protect livestock assets through emergency fodder support", period: "2026", stage: "Rural livelihood protection", description: "The Ministry of Agriculture, FAO and Japan identify emergency fodder support for small-scale livestock keepers as an immediate measure to prevent loss of herds and protect household income in affected southern communities.", actor: "Ministry of Agriculture / FAO / Government of Japan / smallholder livestock keepers", href: "https://www.fao.org/lebanon/news/detail/ministry-of-agriculture-and-fao-launch-japan-funded-project-to-enhance-recovery-and-resilience-of-agrifood-systems-and-rural-livelihoods-in-conflict-affected-areas-of-south-lebanon/en" }
    ,{ name: "Solarise water stations for more resilient service operation", period: "2026", stage: "Sustainable water-service recovery", description: "UNICEF’s water programme supports the solarisation of water stations so service providers can reduce exposure to fuel and electricity interruptions while sustaining safe-water supply.", actor: "UNICEF / Ministry of Energy and Water / Water Establishments / development partners", href: "https://www.unicef.org/lebanon/water-sanitation-and-hygiene-wash-programme" }
    ,{ name: "Strengthen water treatment and quality monitoring", period: "2026", stage: "Water safety and public health", description: "UNICEF supports water establishments with treatment supplies and laboratory equipment so water quality can be monitored and safe-water operations maintained as systems recover from conflict and energy pressures.", actor: "UNICEF / Ministry of Energy and Water / Water Establishments / public-health partners", href: "https://www.unicef.org/lebanon/water-sanitation-and-hygiene-wash-programme" }
    ,{ name: "Strengthen farmer cooperatives and producer organisations", period: "2026", stage: "Collective rural recovery", description: "FAO highlights cooperatives and producer organisations as practical local platforms that help farmers and fishers access markets, services and productive resources while strengthening rural livelihoods and social cohesion.", actor: "FAO / Ministry of Agriculture / cooperatives / producer organisations", href: "https://www.fao.org/lebanon/news/detail/international-day-of-cooperatives--fao-highlights-the-role-of-cooperatives-in-strengthening-rural-communities-in-lebanon/en" }
    ,{ name: "Digitise LEAP finance, procurement and contract-management workflows", period: "2026", stage: "Implementation-system modernisation", description: "LEAP’s project design sets out a staged digitisation of the CDR’s financial-management, procurement and contract-management processes to strengthen the project’s delivery, reporting and accountability systems. This is an implementation commitment, not a completed digital platform.", actor: "Council for Development and Reconstruction / World Bank / LEAP Project Management Unit", href: "https://documents1.worldbank.org/curated/en/099061125095016009/pdf/BOSIB-92339148-e75a-4dca-8bc2-580a6104a46a.pdf" }
    ,{ name: "Undertake technical assessment of investment requirements in damaged areas", period: "2026", stage: "Under implementation", description: "The published LEAP procurement schedule lists technical assistance for assessing investment requirements in damaged areas as under implementation, providing evidence for prioritisation before investment decisions are made.", actor: "Council for Development and Reconstruction / World Bank / technical-assistance provider", href: "https://documents1.worldbank.org/curated/en/099092325113021010/pdf/P509428-0fd29ca4-40c0-4950-83a7-5d5a4a805e23.pdf" }
    ,{ name: "Commission engineering support for quarry-site rubble management", period: "2026", stage: "Under implementation", description: "The published LEAP procurement schedule lists engineering and consulting services for rubble management in quarry sites as under implementation. The register records this as technical delivery support, not as completed rubble processing.", actor: "Council for Development and Reconstruction / Ministry of Environment / World Bank / engineering provider", href: "https://documents1.worldbank.org/curated/en/099092325113021010/pdf/P509428-0fd29ca4-40c0-4950-83a7-5d5a4a805e23.pdf" }
    ,{ name: "Prepare independent third-party monitoring for LEAP delivery", period: "2026", stage: "Under review", description: "LEAP’s public procurement schedule identifies third-party monitoring-agent services as under review, creating an independent assurance layer for implementation once the service is contracted.", actor: "Council for Development and Reconstruction / World Bank / prospective third-party monitor", href: "https://documents1.worldbank.org/curated/en/099092325113021010/pdf/P509428-0fd29ca4-40c0-4950-83a7-5d5a4a805e23.pdf" }
    ,{ name: "Prepare supervision of road clearing and restoration in affected districts", period: "2026", stage: "Pending implementation", description: "The LEAP procurement schedule lists construction-supervision services for damaged-road clearing and restoration in affected southern districts and Beirut’s southern suburbs as pending implementation. This is a preparation record, not confirmation that road works are complete.", actor: "Council for Development and Reconstruction / Ministry of Public Works and Transport / World Bank / supervision provider", href: "https://documents1.worldbank.org/curated/en/099092325113021010/pdf/P509428-0fd29ca4-40c0-4950-83a7-5d5a4a805e23.pdf" }
    ,{ name: "Set an official framework for public-works reform and resilient infrastructure", period: "2026", stage: "Government cooperation framework", description: "The Ministry of Public Works and Transport and UNDP signed a cooperation framework spanning digital transformation, territorial planning, sustainable transport, maritime safety, port development, public-asset sustainability and crisis recovery capacity. It establishes a framework for delivery rather than a list of completed projects.", actor: "Ministry of Public Works and Transport / UNDP / public infrastructure institutions", href: "https://www.undp.org/arab-states/press-releases/ministry-public-works-and-transport-and-undp-sign-partnership-advance-public-sector-reform-and-sustainable-infrastructure" }
    ,{ name: "Train Ministry of Social Affairs shelter coordinators and volunteers", period: "2026", stage: "Completed preparedness support", description: "The Ministry of Social Affairs trained shelter coordinators and volunteers supporting internally displaced people in collective shelters, strengthening service coordination, safeguarding, communication and readiness for future displacement emergencies.", actor: "Ministry of Social Affairs / European Union / UNDP / Permanent Peace Movement / shelter coordinators", href: "https://www.undp.org/lebanon/press-releases/lebanon-recognizes-120-ministry-social-affairs-coordinators-and-volunteers-supporting-displaced-families-during-conflict" }
    ,{ name: "Deploy social workers for collective-shelter protection support", period: "2026", stage: "Shelter service continuity", description: "With UNFPA support, the Ministry of Social Affairs deploys social workers to collective shelters and connects them to protection information, case referrals, psychosocial support and gender-based-violence services.", actor: "Ministry of Social Affairs / UNFPA / shelter protection partners", href: "https://www.unfpa.org/sites/default/files/resource-pdf/UNFPA%20Lebanon%20Situation%20Report%20%282-9%20March%202026%29.pdf" }
    ,{ name: "Validate the National Agriculture Strategy and environmental-social assessment scope", period: "2026", stage: "National strategy validation", description: "The Ministry of Agriculture and FAO validated the strategic framework and environmental and social assessment scope for the National Agriculture Strategy 2026 to 2035, integrating emergency pressures, resilience and long-term sector recovery into national planning.", actor: "Ministry of Agriculture / FAO / line ministries / public agencies / sector stakeholders", href: "https://www.fao.org/lebanon/news/detail/lebanon-validates-strategic-framework-and-sesa-scoping-for-the-national-agriculture-strategy-2026-2035/en" }
    ,{ name: "Implement TVET learning continuity under the Ministry of Education", period: "2026", stage: "Education-service continuity", description: "The Technical and Vocational Education and Training Directorate, with UNICEF technical support, implements a continuity plan that combines safe in-person learning, online options and temporary learning arrangements for displaced and crisis-affected students.", actor: "Ministry of Education and Higher Education / TVET Directorate / UNICEF / education partners", href: "https://www.unicef.org/lebanon/media/14141/file/UNICEF%20Lebanon%20Humanitarian%20Flash%20Update%20No.6%2C%202%20April%202026.pdf" }
    ,{ name: "Establish temporary learning spaces for displaced children", period: "2026", stage: "Education emergency response", description: "In agreement with the Ministry of Education and Higher Education, education partners establish temporary learning spaces that connect displaced children with structured learning, wellbeing support and accessible education options close to where they are staying.", actor: "Ministry of Education and Higher Education / UNICEF / education partners / host schools", href: "https://www.unicef.org/lebanon/children-caught-escalating-violence-lebanon" }
    ,{ name: "Lead responsible public communication during conflict and displacement", period: "2026", stage: "Social cohesion and public information", description: "The Ministry of Information, UNDP and Dawaer Foundation launched a national communication initiative to counter disinformation, reduce divisive narratives and promote reliable, constructive public discourse during conflict and recovery pressures.", actor: "Ministry of Information / UNDP / Dawaer Foundation / media and community partners", href: "https://www.undp.org/lebanon/press-releases/together-we-stay-strong-national-campaign-promote-solidarity-empathy-and-shared-humanity" }
    ,{ name: "Reconnect adolescents and youth to certified technical education pathways", period: "2026", stage: "TVET recovery and inclusion", description: "The Directorate General of Vocational and Technical Education and UNICEF developed a flexible pathway programme that helps out-of-school adolescents and youth re-enter certified technical education after prolonged disruption to learning.", actor: "Directorate General of Vocational and Technical Education / Ministry of Education and Higher Education / UNICEF / Government of the Netherlands", href: "https://www.unicef.org/lebanon/stories/pathways-plus-second-chance-learn-through-tvet-lebanon" }
    ,{ name: "Strengthen cooperative registration and recovery-service capacity", period: "2026", stage: "Institutional livelihood support", description: "Recovery support for conflict-affected cooperatives is linked to General Directorate of Cooperatives registration, while UNDP reports institutional upgrades intended to improve the directorate’s governance and service delivery.", actor: "General Directorate of Cooperatives / Ministry of Agriculture / UNDP / cooperative sector partners", href: "https://www.undp.org/lebanon/stories/france-and-undp-empowering-cooperatives-recovery-lebanon" }
    ,{ name: "Coordinate emergency protection of cultural heritage sites and assets", period: "2026", stage: "Cultural-heritage emergency response", description: "The Directorate General of Antiquities and UNESCO coordinate emergency measures, monitoring and technical response to protect vulnerable heritage sites and movable cultural assets while conflict risks persist.", actor: "Directorate General of Antiquities / Ministry of Culture / UNESCO / site managers / cultural professionals", href: "https://www.unesco.org/en/articles/unesco-and-lebanons-directorate-general-antiquities-discuss-emergency-measures-protect-cultural?hub=802" }
    ,{ name: "Integrate climate risk into sustainable recovery planning", period: "Cross-cutting", stage: "Green recovery governance", description: "The Ministry of Environment’s dedicated Climate Change Directorate is part of an updated institutional vision that links climate resilience, low-carbon policy and more sustainable reconstruction planning.", actor: "Ministry of Environment / Climate Change Directorate / UNDP / national and local partners", href: "https://www.undp.org/lebanon/press-releases/lebanon-launches-climate-policy-package-advance-paris-agreement-goals-and-accelerate-low-carbon-transition" }
    ,{ name: "Strengthen public-integrity safeguards for accountable delivery", period: "Cross-cutting", stage: "Transparency and accountability", description: "The National Anti-Corruption Commission is strengthening access-to-information oversight, whistleblower-protection procedures and evidence-based monitoring mechanisms that support more accountable public administration.", actor: "National Anti-Corruption Commission / public institutions / UNDP / transparency partners", href: "https://www.undp.org/lebanon/projects/anti-corruption-trust-act-lebanon" }
    ,{ name: "Set municipal recovery priorities in Tyre Caza", period: "2024", stage: "Municipal recovery planning", description: "A conflict-sensitive consultation with eight Tyre Caza municipalities identified municipal priorities for solid waste, water and wastewater, flood-risk management, and municipal and agricultural infrastructure. This records jointly identified priorities, not completed works.", actor: "South Tyre Caza municipal partnership / Union of Tyre Municipalities / UNDP / Republic of Korea", href: "https://www.undp.org/lebanon/press-releases/undp-and-republic-korea-increase-support-south-lebanon-communities-affected-recent-conflict" }
    ,{ name: "Anchor local development platforms in municipal governance", period: "2026", stage: "Institutionalisation in preparation", description: "UNDP’s Local Development Project is preparing a formal protocol to anchor local development platforms, local observatories and locally owned plans within Lebanon’s governance framework beyond the project cycle.", actor: "Municipalities / local institutions / Local Development Platforms and Observatories / UNDP / KfW", href: "https://www.undp.org/lebanon/projects/local-development-project-ldp" }
    ,{ name: "Integrate municipal services, livelihoods and social stability", period: "2026", stage: "Area-based local delivery", description: "The Host Communities Support Project links municipal infrastructure, renewable energy, water management and local economic support with dialogue and social-stability measures so services and livelihoods are planned as one local recovery package.", actor: "Municipalities / Unions of Municipalities / UNDP / local economic and community partners", href: "https://www.undp.org/lebanon/projects/lebanon-host-communities-support-project-phase-2-lhsp-20" }
    ,{ name: "Map building destruction and debris for recovery planning", period: "2024", stage: "Damage baseline and recovery planning", description: "UN-Habitat, the University of Balamand and Saint Joseph University assessed building destruction and debris in conflict-affected governorates using satellite imagery and pre-conflict data to support housing rehabilitation and sustainable debris-management planning.", actor: "UN-Habitat / University of Balamand / Saint Joseph University / local and national recovery partners", href: "https://unhabitat.org/BDDQA-Lebanon" }
    ,{ name: "Apply an integrated urban recovery framework", period: "2024", stage: "Urban recovery framework", description: "UN-Habitat’s Urban Crisis Response, Recovery and Reconstruction Framework sets out immediate, medium- and longer-term work on local institutions, adequate housing and protection, and environmental resilience in places affected by the post-October 2023 conflict.", actor: "UN-Habitat / national institutions / municipalities / humanitarian and development partners", href: "https://unhabitat.org/urban-crisis-response-recovery-and-reconstruction-framework-for-lebanon-urfl" }
    ,{ name: "Strengthen Beirut municipal emergency operations", period: "2026", stage: "Municipal emergency service delivery", description: "UNOPS provided specialist municipal equipment that Beirut Municipality mobilised for nighttime rescue, debris clearance, sanitation management and emergency water distribution, strengthening local operational capacity during the response.", actor: "Beirut Municipality / UNOPS / Sustainable Integrated Municipal Actions partners", href: "https://www.unops.org/news-and-stories/stories/on-the-ground-in-lebanon-providing-urgent-relief-and-community-support" }
    ,{ name: "Deliver gender-responsive assistance through women-led organisations", period: "2024", stage: "Protection and community recovery", description: "UN Women and women-led organisations delivered protection support, psychosocial services, hygiene items, hot meals, cash assistance and livelihoods support, including for displaced people in Tyre and other conflict-affected communities.", actor: "UN Women / women-led organisations / Union of Municipalities of Tyre / protection partners", href: "https://open.unwomen.org/en/country-results/LB" }
    ,{ name: "Maintain mobile medical care for displaced and returning communities", period: "2026", stage: "Health-service continuity", description: "MSF scaled up mobile clinics so people who could not safely reach health facilities could access general care, sexual and reproductive health consultations, mental-health support and referrals, including in southern Lebanon and displacement locations.", actor: "Médecins Sans Frontières / Ministry of Public Health / local health facilities and responders", href: "https://www.msf.org/msf-scales-response-lebanon-displacement-rises" }
    ,{ name: "Supply priority medicines to public hospitals", period: "2026", stage: "Hospital service support", description: "Anera supplied priority intravenous medicines requested by the Ministry of Public Health to help public hospitals manage conflict- and displacement-related pressure on emergency and inpatient care.", actor: "Anera / Ministry of Public Health / Americares / public hospitals", href: "https://www.anera.org/stories/supporting-lebanons-hospitals-with-medicines-during-a-time-of-crisis/" }
    ,{ name: "Restore child protection and learning support in shelters", period: "2026", stage: "Child-focused recovery support", description: "Save the Children provides child-protection services, safe spaces, learning materials and shelter learning spaces, alongside essential household items and water, sanitation and hygiene support for displaced families.", actor: "Save the Children / local partners / education and protection partners", href: "https://www.savethechildren.net/what-we-do/emergencies/lebanon-crisis" }
    ,{ name: "Clarify reconstruction rights for affected households", period: "2026", stage: "Housing and property rights support", description: "NRC’s legal brief explains the reconstruction law’s provisions on tax exemptions, fee waivers, deadline suspensions and the legal status of destroyed structures, helping make housing and property implications visible in recovery discussions.", actor: "Norwegian Refugee Council / legal and housing-rights stakeholders", href: "https://www.nrc.no/resources/briefing-notes/legal-brief-on-law-no.-222025-the-reconstruction-law" }
    ,{ name: "Register displaced families for targeted early recovery support", period: "2024", stage: "Targeted-assistance system", description: "The Ministry of Social Affairs, UNICEF and WFP established a national registration arrangement for internally displaced people, creating a shared basis for more targeted support during early recovery and reconstruction.", actor: "Ministry of Social Affairs / UNICEF / World Food Programme / national response partners", href: "https://www.unicef.org/lebanon/emergency-response-lebanon" }
    ,{ name: "Provide integrated care for war-wounded and affected children", period: "2024", stage: "Child health and rehabilitation", description: "The Ministry of Public Health, UNICEF and partners support the Assistance and Care for War-Wounded and Affected Children programme, combining medical, psychosocial and rehabilitation support for children affected by the 2024 conflict.", actor: "Ministry of Public Health / UNICEF / health and rehabilitation partners", href: "https://www.unicef.org/lebanon/health" }
    ,{ name: "Engage youth in shelter response and paid skills pathways", period: "2026", stage: "Youth livelihood and shelter support", description: "UNICEF’s Learning to Earning programme enables young people to support emergency response in shelters while building practical skills and earning income through activities such as meal preparation and essential-item production.", actor: "UNICEF / KfW / youth participants / shelter partners", href: "https://www.unicef.org/lebanon/stories/lebanons-shelters-youth-are-stepping-when-it-matters-most" }
    ,{ name: "Establish protection groups for displaced girls in shelters", period: "2026", stage: "Planned protection outreach", description: "UNICEF’s emergency response planning includes POWER4Girls sessions and girls’ groups in shelters and community centres to extend safe, age-appropriate support to displaced girls. The register records this as planned outreach.", actor: "UNICEF / Ministry of Social Affairs / protection partners / shelter teams", href: "https://www.unicef.org/media/179621/file/Lebanon-Humanitarian-Situation-Report-No.1%28Escalation-of-Hostilities%29-19-March-2026.pdf.pdf" }
